/**
 * Complete About Us page. This page is front-end only (no Laravel API requests).
 * Header and Footer are provided by the shared router components.
 */
export function About() {
  return [BREADCRUMB, ABOUT_INTRO, TREATMENT, TEAM,  FAQ].join('\n');
}

/** Register page behavior after the HTML has been rendered into #app. */
export function initAbout() {
  initTreatmentTabs();
  initFaqAccordion();
  initTestimonialSlider();
}

function initTreatmentTabs() {
  const root = document.querySelector('.treatment-section.two .tretment-tabs.w-tabs');
  if (!root) return;

  const links = [...root.querySelectorAll('.w-tab-menu .w-tab-link[data-w-tab]')];
  const panes = [...root.querySelectorAll('.w-tab-content .w-tab-pane[data-w-tab]')];
  const menu = root.querySelector('.w-tab-menu');
  menu?.setAttribute('role', 'tablist');

  function activate(key) {
    root.dataset.current = key;
    for (const link of links) {
      const selected = link.dataset.wTab === key;
      link.classList.toggle('w--current', selected);
      link.setAttribute('role', 'tab');
      link.setAttribute('aria-selected', String(selected));
      link.setAttribute('tabindex', selected ? '0' : '-1');

      const details = link.querySelector('.tretment-tab-content-block');
      if (details) details.style.display = selected ? 'block' : 'none';
    }
    for (const pane of panes) {
      const selected = pane.dataset.wTab === key;
      pane.classList.toggle('w--tab-active', selected);
      pane.setAttribute('role', 'tabpanel');
      pane.hidden = !selected;
    }
  }

  links.forEach((link, index) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      activate(link.dataset.wTab);
    });
    link.addEventListener('keydown', (event) => {
      const direction = (event.key === 'ArrowRight' || event.key === 'ArrowDown') ? 1
        : (event.key === 'ArrowLeft' || event.key === 'ArrowUp') ? -1 : 0;
      if (!direction) return;
      event.preventDefault();
      const next = links[(index + direction + links.length) % links.length];
      activate(next.dataset.wTab);
      next.focus();
    });
  });
  activate(root.dataset.current || links[0]?.dataset.wTab);
}

function initFaqAccordion() {
  const root = document.querySelector('.faq-section .faq-tabs.w-tabs');
  if (!root) return;

  const links = [...root.querySelectorAll('.faq-tab-menu .faq-tab-link[data-w-tab]')];
  const panes = [...root.querySelectorAll('.faq-tab-content .w-tab-pane[data-w-tab]')];
  const menu = root.querySelector('.faq-tab-menu');
  menu?.setAttribute('role', 'tablist');
  let current = root.dataset.current || links[0]?.dataset.wTab;

  function activate(key) {
    current = key;
    root.dataset.current = key;
    links.forEach((link) => {
      const selected = key === link.dataset.wTab;
      link.classList.toggle('w--current', selected);
      link.setAttribute('role', 'tab');
      link.setAttribute('tabindex', selected ? '0' : '-1');
      link.setAttribute('aria-selected', String(selected));
      link.setAttribute('aria-expanded', String(selected));

      const answer = link.querySelector('.ans-box');
      if (answer) {
        answer.style.overflow = 'hidden';
        answer.style.transition = 'height 300ms ease';
        answer.style.height = selected ? `${answer.scrollHeight}px` : '0px';
        answer.setAttribute('aria-hidden', String(!selected));
      }
      const icon = link.querySelector('.faq-icon-main-wrap');
      if (icon) icon.classList.toggle('is-open', selected);
      const plus = link.querySelector('.plus');
      if (plus) plus.style.transform = selected ? 'rotate(90deg)' : 'rotate(0deg)';
    });
    panes.forEach((pane) => {
      const selected = pane.dataset.wTab === key;
      pane.classList.toggle('w--tab-active', selected);
      pane.hidden = !selected;
    });
  }

  links.forEach((link, index) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      // Webflow-style accordion: show one answer at a time.
      activate(link.dataset.wTab);
    });
    link.addEventListener('keydown', (event) => {
      const delta = (event.key === 'ArrowDown' || event.key === 'ArrowRight') ? 1
        : (event.key === 'ArrowUp' || event.key === 'ArrowLeft') ? -1 : 0;
      if (!delta) return;
      event.preventDefault();
      const next = links[(index + delta + links.length) % links.length];
      activate(next.dataset.wTab);
      next.focus();
    });
  });

  activate(current);
}

function initTestimonialSlider() {
  const root = document.querySelector('.testimonial-section .testimonial-slider.w-slider');
  if (!root) return;

  const mask = root.querySelector('.w-slider-mask');
  const slides = [...mask?.querySelectorAll(':scope > .w-slide') || []];
  const prev = root.querySelector('.w-slider-arrow-left');
  const next = root.querySelector('.w-slider-arrow-right');
  const nav = root.querySelector('.w-slider-nav');
  if (!mask || !slides.length) return;

  mask.style.display = 'flex';
  mask.style.overflow = 'hidden';
  slides.forEach((slide) => {
    slide.style.flex = '0 0 100%';
    slide.style.width = '100%';
    slide.style.transition = 'transform 500ms ease';
  });

  let index = 0;
  const infinite = root.dataset.infinite !== 'false';
  const dots = slides.map((_, i) => {
    const dot = document.createElement('button');
    dot.type = 'button';
    dot.className = 'w-slider-dot';
    dot.setAttribute('aria-label', `Go to testimonial ${i + 1}`);
    dot.addEventListener('click', () => show(i));
    nav?.appendChild(dot);
    return dot;
  });

  function show(value) {
    index = infinite ? (value + slides.length) % slides.length
      : Math.max(0, Math.min(slides.length - 1, value));
    slides.forEach((slide, i) => {
      slide.style.transform = `translateX(-${index * 100}%)`;
      slide.setAttribute('aria-hidden', String(i !== index));
    });
    dots.forEach((dot, i) => {
      const selected = i === index;
      dot.classList.toggle('w-active', selected);
      dot.setAttribute('aria-current', selected ? 'true' : 'false');
    });
  }

  for (const [button, step, label] of [[prev, -1, 'Previous testimonial'], [next, 1, 'Next testimonial']]) {
    if (!button) continue;
    button.setAttribute('role', 'button');
    button.setAttribute('tabindex', '0');
    button.setAttribute('aria-label', label);
    button.addEventListener('click', () => show(index + step));
    button.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        show(index + step);
      }
    });
  }

  let startX = null;
  mask.addEventListener('touchstart', (event) => {
    startX = event.changedTouches[0]?.clientX ?? null;
  }, { passive: true });
  mask.addEventListener('touchend', (event) => {
    const endX = event.changedTouches[0]?.clientX;
    if (startX === null || endX === undefined) return;
    const distance = startX - endX;
    if (Math.abs(distance) > 40) show(index + Math.sign(distance));
    startX = null;
  }, { passive: true });

  show(0);
}
